import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    pts = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(pts)}
    m = len(pts)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    inf = 10**18
    pot = [inf] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    total_cost = 0
    rem = k

    while rem > 0:
        dist = [inf] * m
        dist[0] = 0
        parent_v = [-1] * m
        parent_e = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[m - 1] == inf:
            break

        for v in range(m):
            if dist[v] < inf:
                pot[v] += dist[v]

        if pot[m - 1] >= 0:
            break

        flow = rem
        v = m - 1
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            cap = adj[u][ei][1]
            if cap < flow:
                flow = cap
            v = u

        v = m - 1
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= flow
            adj[v][edge[3]][1] += flow
            v = u

        total_cost += flow * pot[m - 1]
        rem -= flow

    return -total_cost
